-- Local bounded-history fixture; no approval or send attestation.
do $$declare n integer;confirmation uuid;token uuid;begin for n in 2..61 loop
 confirmation:=gen_random_uuid();token:=gen_random_uuid();insert into collect_hybrid.sms_notification_confirmations select(jsonb_populate_record(null::collect_hybrid.sms_notification_confirmations,to_jsonb(c)||jsonb_build_object('id',confirmation,'claim_token',token,'fence_version',n,'approved_at',clock_timestamp()-n*interval '1 second','expires_at',clock_timestamp()+interval '1 hour','consumed_at',null))).* from collect_hybrid.sms_notification_confirmations c where c.id='746eac12-026b-4fbd-8fbe-206604bfb25e';
 insert into collect_hybrid.sms_notification_attempts select(jsonb_populate_record(null::collect_hybrid.sms_notification_attempts,to_jsonb(a)||jsonb_build_object('id',gen_random_uuid(),'confirmation_id',confirmation,'claim_token',token,'fence_version',n,'attempt_number',n,'state','uncertain','outcome_at',clock_timestamp(),'evidence_reference','synthetic bounded history','outcome_note','No carrier called'))).* from collect_hybrid.sms_notification_attempts a where a.id='68b4e9f4-e3f5-486f-bed9-0a84ed6b1179';end loop;end$$;
